    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int cap = Integer.parseInt(st.nextToken()), K = Integer.parseInt(st.nextToken());
        int[] ranks = new int[K];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) ranks[i] = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(br.readLine().trim());
        boolean[] isPut = new boolean[q];
        int[] keys = new int[q], values = new int[q];
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            isPut[i] = st.nextToken().equals("PUT");
            keys[i] = Integer.parseInt(st.nextToken());
            if (isPut[i]) values[i] = Integer.parseInt(st.nextToken());
        }
        StringBuilder sb = new StringBuilder();
        for (int x : run(cap, ranks, isPut, keys, values)) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
